"""Image perception boundary: projection, confirmation, frame synchronisation, degradation."""
import base64
import io
import math
import os
from pathlib import Path

import numpy as np
import pytest
from fastapi.testclient import TestClient

from rescuetwin import api
from rescuetwin.core import Simulation
from rescuetwin.perception import Detection, back_project, camera_to_world, process_frame

# Generated by the headless gate run (see docs/DEVELOPMENT.md); kept in ignored data/, not in source.
SAMPLE = Path(__file__).resolve().parent.parent / 'data' / 'test-frames' / 'rendered_frame.npz'


def test_camera_to_world_follows_yaw():
    pose = dict(x=1., y=2., z=1., yaw=math.pi / 2)            # facing +y
    x, y, z = camera_to_world([0.5, 0.2, 3.0], pose)          # 3 m ahead, 0.5 m right, 0.2 m below
    assert math.isclose(x, 1.5, abs_tol=1e-9) and math.isclose(y, 5.0, abs_tol=1e-9) and math.isclose(z, .8)


def test_back_project_uses_box_centre_depth():
    depth = np.full((100, 100), 9.0, np.float32)
    depth[20:90, 40:60] = 3.0                                 # person in front of a far wall
    position = back_project([40, 20, 60, 90], depth, (50., 50., 50., 50.))
    assert math.isclose(position[2], 3.0) and abs(position[0]) < 1e-6


class FakeDetector:
    def __init__(self, boxes):
        self.boxes = boxes

    def detect(self, image, depth, intrinsics):
        return [Detection(b, .9, back_project(b, depth, intrinsics)) for b in self.boxes]


def image_sim(survivors=([3, 6],)):
    sim = Simulation(scenario=dict(survivors=[list(s) for s in survivors], ignitions=[], seed=1), perception='image-yolo')
    sim.status = 'running'
    return sim


def test_image_mode_needs_two_consistent_frames_and_ignores_truth():
    sim = image_sim()
    for _ in range(30):
        sim.tick()
        if sim.frame_request:
            sim.frame_request = None
    assert not sim.detections                                  # truth alone never creates evidence
    d = sim.add_evidence((2.0, 3.0), .8, 'yolo')
    assert d['status'] == 'candidate'
    assert sim.add_evidence((2.3, 3.1), .7, 'yolo') is d and d['status'] == 'confirmed'
    other = sim.add_evidence((6.0, 3.0), .8, 'yolo')
    assert other is not d and other['status'] == 'candidate'


def test_false_detection_is_retired_on_arrival():
    sim = image_sim(survivors=())
    d = sim.add_evidence(sim.scene.world((3, 6)), .9, 'yolo'); sim.add_evidence(sim.scene.world((3, 6)), .9, 'yolo')
    sim.robot = (3, 6); sim.pair()
    assert d['status'] == 'not-found' and sim.metrics['false_detections'] == 1


def encode_frame(rgb, depth):
    from PIL import Image
    buffer = io.BytesIO(); Image.fromarray(rgb).save(buffer, 'PNG')
    return 'data:image/png;base64,' + base64.b64encode(buffer.getvalue()).decode(), base64.b64encode(depth.astype('<f4').tobytes()).decode()


def frame_body(request, rgb, depth, **overrides):
    image, depth64 = encode_frame(rgb, depth)
    h, w = depth.shape
    body = dict(seq=request['seq'], width=w, height=h, rgb=image, depth=depth64,
                intrinsics=[w / 2, w / 2, w / 2, h / 2], pose=request['pose'])
    body.update(overrides)
    return body


def test_frame_endpoint_synchronises_and_projects(monkeypatch):
    with TestClient(api.app) as client:
        api.sim = image_sim()
        api.sim.request_frame()
        request = api.sim.frame_request
        monkeypatch.setattr(api, 'detector', FakeDetector([[28, 10, 36, 54]]))
        rgb = np.zeros((60, 64, 3), np.uint8); depth = np.full((60, 64), 2.0, np.float32)
        stale = frame_body(request, rgb, depth, seq=request['seq'] + 1)
        assert client.post('/api/frames', json=stale).status_code == 409
        moved = frame_body(request, rgb, depth, pose={**request['pose'], 'x': request['pose']['x'] + 1})
        assert client.post('/api/frames', json=moved).status_code == 409
        response = client.post('/api/frames', json=frame_body(request, rgb, depth))
        assert response.status_code == 200, response.text
        accepted = response.json()['accepted']
        assert accepted and accepted[0]['detection'] == 'det-0'
        assert math.isclose(math.dist(accepted[0]['world'][:2], (request['pose']['x'], request['pose']['y'])), 2.0, abs_tol=.15)
        assert api.sim.frame_request is None
        observation = client.get('/api/observations').json()
        assert 'person-' not in str(observation)
        client.post('/api/control', json={'action': 'reset', 'perception': 'analytic-development'})


def test_missing_frames_degrade_instead_of_blocking(monkeypatch):
    monkeypatch.setattr(api, 'FRAME_TIMEOUT_S', 0.0)
    api.sim = image_sim(); api.sim.request_frame()
    api.frame_timeout_check(); api.frame_timeout_check()
    assert api.sim.frame_request is None and api.sim.degraded
    assert any('degraded' in e['message'] for e in api.sim.events)


@pytest.mark.skipif(os.environ.get('RESCUETWIN_YOLO_TEST') != '1' or not SAMPLE.exists(),
                    reason='opt-in: set RESCUETWIN_YOLO_TEST=1 (needs vision extra and YOLO weights)')
def test_real_yolo_detects_rendered_avatar():
    from rescuetwin.perception import PersonDetector
    from PIL import Image
    data = np.load(SAMPLE)
    pose = dict(zip(('x', 'y', 'z', 'yaw'), data['pose'].tolist()))
    accepted, _ = process_frame(PersonDetector(), Image.open(io.BytesIO(data['rgb_jpeg'].tobytes())).convert('RGB'), data['depth'], data['intrinsics'].tolist(), pose, 4.0)
    assert accepted, 'YOLO found no person in the rendered sample frame'
    assert math.dist(accepted[0]['world'][:2], data['avatar'][:2].tolist()) < .75
